<script setup lang="ts">import{ref,onMounted,onUnmounted,computed,watch}from'vue';import Tooltip from'./Tooltip.vue';import{useGatewayStore}from'../stores/gateway';import{buildThemeColors,type ThemeColors}from'../utils/themeColors'
interface Td{id:string;label:string;swatches:string[]}
const BUILTIN:Td[]=[{id:'amber',label:'Amber',swatches:['#FFD700','#FFBF00','#CC9B1F']},{id:'blue',label:'Blue',swatches:['#44AAFF','#4499FF','#5588BB']},{id:'rose',label:'Rose',swatches:['#FF6699','#FF5599','#CC6699']},{id:'emerald',label:'Emerald',swatches:['#00E676','#00C853','#00897B']},{id:'purple',label:'Purple',swatches:['#CE93D8','#BA68C8','#8E24AA']}]
const p=defineProps<{current:string;onChange:(id:string,hex?:string)=>void}>()
const gw=useGatewayStore();const colors=ref<Record<string,ThemeColors>>({})
const o=ref(false);const sp=ref(false);const err=ref('');const rr=ref<HTMLDivElement|null>(null);const ct=ref<Td[]>([])
const r=ref(255);const g=ref(215);const b=ref(0)
const hv=computed(()=>{const th=(v:number)=>Math.max(0,Math.min(255,v)).toString(16).padStart(2,'0');return`#${th(r.value)}${th(g.value)}${th(b.value)}`.toUpperCase()})
async function ldct(){try{const r=await gw.request<{theme:{custom:any[];colors:Record<string,ThemeColors>}}>('theme.get');const list=r?.theme?.custom;ct.value=Array.isArray(list)?list.filter(t=>t&&typeof t.id==='string'):[];colors.value=r?.theme?.colors&&typeof r.theme.colors==='object'?r.theme.colors:{}}catch{ct.value=[];colors.value={}}}
async function svct(){const hex=hv.value;err.value='';const d=buildThemeColors(hex);const id=`custom-${Date.now()}`;const t:Td={id,label:`Custom ${hex}`,swatches:[d.primary,d.accent,d.muted]};const next=(Array.isArray(ct.value)?ct.value:[]).concat(t);ct.value=next;colors.value={...colors.value,[id]:d};sp.value=false;o.value=false;p.onChange(id,hex);try{const r=await gw.request<{success:boolean}>('theme.save',{theme:{current:id,custom:next,colors:colors.value}});if(!r?.success)err.value='Theme applied, but saving failed'}catch(e){err.value='Theme applied, but saving failed: '+(e instanceof Error?e.message:String(e))}}
async function dlct(id:string){ct.value=ct.value.filter(t=>t.id!==id);const nextColors={...colors.value};delete nextColors[id];colors.value=nextColors;const cur=p.current===id?'amber':p.current;if(p.current===id)p.onChange('amber');try{await gw.request('theme.save',{theme:{current:cur,custom:ct.value,colors:nextColors}})}catch{}}
function opnpk(){if(p.current.startsWith('custom-')){const c=colors.value[p.current];if(c&&c.primary){const h=c.primary;r.value=parseInt(h.slice(1,3),16);g.value=parseInt(h.slice(3,5),16);b.value=parseInt(h.slice(5,7),16)}}sp.value=true}
function ap(){const hex=hv.value;const d=buildThemeColors(hex);const rt=document.getElementById('app');if(!rt)return;rt.style.setProperty('--primary',d.primary);rt.style.setProperty('--accent',d.accent);rt.style.setProperty('--muted',d.muted);rt.style.setProperty('--border-gold',d.borderGold);rt.style.setProperty('--glow-start',d.glowStart);rt.style.setProperty('--glow-end',d.glowEnd)}
function hco(e:MouseEvent){if(rr.value&&!rr.value.contains(e.target as Node)){o.value=false;sp.value=false}}
async function st(id:string){p.onChange(id);o.value=false;sp.value=false;try{await gw.request('theme.save',{theme:{current:id}})}catch{}}
onMounted(()=>{ldct();document.addEventListener('mousedown',hco)});onUnmounted(()=>document.removeEventListener('mousedown',hco))
watch(()=>gw.connected,v=>{if(v)ldct()})
function hsc(){ap()};function hni(){ap()};function ccpk(){sp.value=false;err.value='';p.onChange(p.current)}
</script>
<template><div ref="rr" class="theme-swt"><Tooltip text="Theme" position="bottom"><button class="mc-btn theme-btn" @click="o=!o" aria-label="Switch theme"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg></button></Tooltip>
<div v-if="o" class="theme-dropdown"><div v-for="t in BUILTIN" :key="t.id" class="theme-opt" :class="{active:t.id===current}" @click="st(t.id)"><div class="theme-swatch-row"><span v-for="(c,i) in t.swatches" :key="i" class="theme-swatch" :style="{background:c}"/></div><span class="theme-opt-label">{{t.label}}</span><svg v-if="t.id===current" class="theme-check" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg></div>
<div class="theme-sep"/>
<div v-for="t in ct" :key="t.id" class="theme-opt" :class="{active:t.id===current}"><div class="theme-opt-main" @click="st(t.id)"><div class="theme-swatch-row"><span v-for="(c,i) in t.swatches" :key="i" class="theme-swatch" :style="{background:c}"/></div><span class="theme-opt-label">{{t.label}}</span><svg v-if="t.id===current" class="theme-check" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg></div><button class="theme-del-btn" @click.stop="dlct(t.id)" title="Delete"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button></div>
<button class="theme-add-btn" @click="opnpk"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg><span>Custom Color</span></button></div>
<div v-if="sp" class="theme-picker-panel"><div class="picker-header">Custom Color</div><div class="picker-preview-row"><div class="picker-preview" :style="{background:hv}"/><span class="picker-hex">{{hv}}</span></div>
<div class="picker-row"><span class="picker-label">R</span><input type="range" class="picker-slider" min="0" max="255" v-model.number="r" @input="hsc" :style="{'--slider-color':`rgb(${r},0,0)`}"/><input type="number" class="picker-num" min="0" max="255" v-model.number="r" @input="hni"/></div>
<div class="picker-row"><span class="picker-label">G</span><input type="range" class="picker-slider" min="0" max="255" v-model.number="g" @input="hsc" :style="{'--slider-color':`rgb(0,${g},0)`}"/><input type="number" class="picker-num" min="0" max="255" v-model.number="g" @input="hni"/></div>
<div class="picker-row"><span class="picker-label">B</span><input type="range" class="picker-slider" min="0" max="255" v-model.number="b" @input="hsc" :style="{'--slider-color':`rgb(0,0,${b})`}"/><input type="number" class="picker-num" min="0" max="255" v-model.number="b" @input="hni"/></div>
<div v-if="err" class="picker-error">{{err}}</div><div class="picker-actions"><button class="picker-btn picker-btn-cancel" @click="ccpk">Cancel</button><button class="picker-btn picker-btn-save" @click="svct">Save</button></div></div></div></template>
<style scoped>.theme-sep{height:1px;background:var(--border-subtle);margin:4px 6px}.theme-add-btn{display:flex;align-items:center;gap:6px;width:100%;padding:6px 8px;border:none;border-radius:6px;background:transparent;color:var(--muted);font-family:var(--font-mono);font-size:11px;cursor:pointer;transition:all .15s}.theme-add-btn:hover{background:var(--bg-hover);color:var(--accent)}.theme-opt-main{display:flex;align-items:center;gap:8px;flex:1;cursor:pointer}.theme-del-btn{display:flex;align-items:center;justify-content:center;width:20px;height:20px;border:none;border-radius:4px;background:transparent;color:var(--muted);cursor:pointer;flex-shrink:0;transition:all .15s}.theme-del-btn:hover{background:rgba(239,83,80,.15);color:var(--error)}.theme-picker-panel{position:absolute;top:100%;left:0;margin-top:6px;width:220px;background:var(--bg-surface);border:1px solid var(--border-subtle);border-radius:8px;box-shadow:0 8px 32px rgba(0,0,0,.5);z-index:201;padding:10px;animation:mc-in .15s var(--spring)}.picker-header{font-family:var(--font-mono);font-size:11px;color:var(--text);margin-bottom:8px;font-weight:600}.picker-preview-row{display:flex;align-items:center;gap:10px;margin-bottom:10px}.picker-preview{width:32px;height:32px;border-radius:6px;border:1px solid rgba(255,255,255,.15);flex-shrink:0}.picker-hex{font-family:var(--font-mono);font-size:13px;color:var(--text);font-weight:600}.picker-row{display:flex;align-items:center;gap:6px;margin-bottom:6px}.picker-label{font-family:var(--font-mono);font-size:11px;color:var(--muted);width:16px;flex-shrink:0}.picker-slider{-webkit-appearance:none;appearance:none;flex:1;height:4px;background:var(--border-subtle);border-radius:2px;outline:none;cursor:pointer}.picker-slider::-webkit-slider-thumb{-webkit-appearance:none;width:14px;height:14px;border-radius:50%;background:var(--slider-color,var(--accent));border:2px solid var(--bg-surface);cursor:pointer;transition:transform .15s}.picker-slider::-webkit-slider-thumb:hover{transform:scale(1.2)}.picker-num{width:42px;height:24px;background:var(--bg-input);border:1px solid var(--border-subtle);border-radius:4px;color:var(--text);font-family:var(--font-mono);font-size:11px;text-align:center;outline:none;flex-shrink:0}.picker-num:focus{border-color:var(--accent)}.picker-num::-webkit-inner-spin-button,.picker-num::-webkit-outer-spin-button{-webkit-appearance:none;margin:0}.picker-error{font-size:10px;color:var(--error);margin-top:6px;line-height:1.4;word-break:break-word}.picker-actions{display:flex;gap:6px;margin-top:10px}.picker-btn{flex:1;padding:6px 0;border:none;border-radius:6px;font-family:var(--font-mono);font-size:11px;cursor:pointer;transition:all .15s}.picker-btn-cancel{background:var(--bg-hover);color:var(--text-body)}.picker-btn-cancel:hover{background:var(--border-subtle)}.picker-btn-save{background:var(--accent);color:var(--bg-deep);font-weight:600}.picker-btn-save:hover{filter:brightness(1.1)}</style>
